from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class AdministrativeStateSlot(SchemaObject):
    locked = SchemaField(name="locked")
    unlocked = SchemaField(name="unlocked")

    def __init__(self, locked, unlocked):
        self.locked = locked
        self.unlocked = unlocked
        super(AdministrativeStateSlot, self).__init__()


class F1LinkStatusSlot(SchemaObject):
    available = SchemaField(name="available")
    unavailable = SchemaField(name="unavailable")

    def __init__(self, available, unavailable):
        self.available = available
        self.unavailable = unavailable
        super(F1LinkStatusSlot, self).__init__()


class DuStatesASMV1(SchemaObject):
    administrative_state = SchemaField(name="administrativeState", not_null=True, klass=AdministrativeStateSlot)
    f1_link_status = SchemaField(name="f1LinkStatus", not_null=True, klass=F1LinkStatusSlot)
    total = SchemaField(name="total", not_null=True)

    def __init__(self, administrative_state, f1_link_status, total):
        self.administrative_state = administrative_state
        self.f1_link_status = f1_link_status
        self.total = total

        super(DuStatesASMV1, self).__init__()
